use anyhow::{Result,ensure};
use sarv_quote::{domain::{State,OrderLine,Unit,now},imports::{catalog_csv,accept_catalog},sales::SalesCommand,store::Store};
use serde_json::json;
use std::{fs,path::PathBuf};
fn main()->Result<()> {
    let input=PathBuf::from(std::env::args().nth(1).expect("actual interleaved state"));let out=PathBuf::from(std::env::args().nth(2).expect("fresh private output"));fs::create_dir_all(&out)?;
    let mut state:State=serde_json::from_slice(&fs::read(input)?)?;let company=state.accounting.companies[0].id.clone();let period=state.accounting.periods[0].id.clone();let at=now();let date=&at[..10];
    let catalog=catalog_csv(&format!("code,name,measure,price,currency,source_at,aliases\nA,کالای مستقل,piece,17,rial,{at},reviewer-alias\n"),"Independent authentic quotation catalog")?;accept_catalog(&mut state,catalog)?;
    state.draft.customer="dual role A".into();state.draft.phone="09123456789".into();state.draft.customer_contact="تماس مصنوعی".into();state.draft.customer_email="reviewer@example.invalid".into();state.draft.customer_address="نشانی مصنوعی مستقل".into();
    state.draft.lines=vec![OrderLine{query:"A".into(),quantity_milli:3000,chosen_code:Some("A".into())}];state.draft.discount_rial=2;state.draft.tax_basis_points=0;state.draft.display_unit=Unit::Toman;state.draft.quote_date=date.into();state.draft.valid_until=date.into();state.draft.notes="Original independent quote notes".into();state.draft.terms="Original independent terms".into();state.draft.issuer_name="سَرو • بررسی مستقل".into();state.draft.issuer_phone="02112345678".into();state.draft.issuer_address="نشانی صادرکننده".into();state.draft.header="سربرگ اصلی".into();state.draft.footer="پابرگ اصلی".into();
    let quote_id=state.approve()?;let quote=state.quotes.iter().find(|q|q.id==quote_id).unwrap().clone();ensure!(quote.total_rial==49&&quote.discount_rial==2&&quote.tax_rial==0,"independent qty3×price17−discount2=49");state.validate()?;
    let original_quotes=serde_json::to_value(&state.quotes)?;let mut draft=state.sales_draft_from_quote(&quote_id,&company)?;ensure!(draft.lines[0].warehouse_id.is_empty(),"two warehouses require explicit selection");draft.lines[0].warehouse_id="w1".into();ensure!(draft.lines[0].unit_price=="1.7"&&draft.document_discount=="0.2"&&draft.supplied_total=="4.9","exact residual toman, no changing economic values");
    let id=draft.id.clone();let valid=draft.clone();draft.lines[0].quantity="۳.".into();draft.lines[0].unit_price="1.71".into();draft.financial_date="نامعتبر".into();
    let mut store=Store::open(&out.join("profile"))?;store.change(|s|{*s=state;Ok(())})?;store.change(|s|s.save_sales_draft(draft,None))?;
    let invalid_before=serde_json::to_value(&store.state)?;let generation=store.local_generation();ensure!(store.change(|s|s.post_sales_from_draft(&id,1,"invalid-submit","reviewer")).is_err()&&serde_json::to_value(&store.state)?==invalid_before&&store.local_generation()==generation,"failed submit retains exact raw invalid draft and generation");
    store.backup(&out.join("invalid-raw-backup.json"))?;drop(store);let mut store=Store::open(&out.join("profile"))?;ensure!(serde_json::to_value(&store.state)?==invalid_before,"invalid raw Persian/incomplete/fractionalrial date values survive restart");
    let mut valid=valid;valid.revision=1;ensure!(store.change(|s|s.save_sales_draft(valid,Some(1)))?==2,"corrected raw draft revision2");
    let order=store.state.sales_order_from_draft(&id,2,"authentic-submit","reviewer")?;ensure!(order.supplied_total.rials()==49&&order.lines[0].unit_price.rials()==17&&order.document_discount.rials()==2,"canonical order preserves49IRR/17IRR/2IRR");
    let mut observations=vec![];
    for field in ["notes","terms","issuer_name","issuer_phone","issuer_address","header","footer","customer_contact","customer_email","customer_address","phone","display_unit","quote_date","valid_until"] {
        let mut value=serde_json::to_value(&store.state)?;let q=&mut value["quotes"][0];q[field]=match field {"display_unit"=>json!("Rial"),"quote_date"|"valid_until"=>json!("2026-10-07"),_=>json!("changed immutable source metadata")};
        let changed:State=serde_json::from_value(value)?;ensure!(changed.validate_sales_quotation(&order).is_err(),"full approved source SHA must cover {field}");observations.push(json!({"check":format!("authentic quote metadata {field}"),"result":"full_snapshot_rejected"}));
    }
    for (name,edit) in [("wrong source line index",0u8),("changed price source reference",1),("changed amount one rial",2),("changed unit mapping",3),("fabricated approved hash",4)] {
        let mut value=serde_json::to_value(&order)?;match edit {0=>value["quotation"]["source_line_indices"][0]=1.into(),1=>value["lines"][0]["price_reference"]="fabricated source".into(),2=>value["lines"][0]["unit_price"]=18.into(),3=>value["lines"][0]["unit_id"]="carton".into(),_=>value["quotation"]["quote_sha256"]="0".repeat(64).into()};
        let changed=serde_json::from_value(value)?;ensure!(store.state.validate_sales_quotation(&changed).is_err(),"authentic conversion rejects {name}");observations.push(json!({"check":name,"result":"source_conversion_rejected"}));
    }
    let result=store.change(|s|s.post_sales_from_draft(&id,2,"authentic-submit","reviewer"))?;ensure!(result.journal_id.is_none()&&store.state.sales_drafts.is_empty()&&serde_json::to_value(&store.state.quotes)?==original_quotes,"post exact authentic order/removes draft atomically/preserves all quotation bytes");
    store.change(|s|s.accounting.set_period_lock(&period,true,"reviewer","Independent locked retry after completed draft"))?;drop(store);let mut store=Store::open(&out.join("profile"))?;let before=store.state.accounting.clone();let generation_after_lock=store.local_generation();ensure!(store.change(|s|s.post_sales_from_draft(&id,2,"authentic-submit","reviewer"))?==result&&store.state.accounting==before&&store.local_generation()==generation_after_lock,"identical lost-receipt retry after restart/lock exact no-op");
    ensure!(store.change(|s|s.post_sales_from_draft(&id,2,"authentic-submit-alias","reviewer"))?==result&&store.state.accounting.journals==before.journals&&store.state.accounting.sales.records==before.sales.records&&store.state.accounting.audit==before.audit,"new-key lost-receipt alias creates no second effect");
    let before=serde_json::to_value(&store.state)?;ensure!(store.change(|s|s.post_sales_from_draft(&id,2,"actor-conflict","different reviewer")).is_err()&&serde_json::to_value(&store.state)?==before,"different actor locked completed retry rejects unchanged");
    let posted_order=match &store.state.accounting.sales.records.last().unwrap().command{SalesCommand::Order(o)=>o.clone(),_=>unreachable!()};let mut duplicate=posted_order;duplicate.context.source_id="duplicate-conversion-source".into();duplicate.context.request_key="duplicate-conversion-key".into();duplicate.lines[0].id="duplicate-conversion-line".into();duplicate.reference="DIFFERENT-REFERENCE".into();
    let mut unlocked=store.state.clone();unlocked.accounting.set_period_lock(&period,false,"reviewer","Independent duplicate conversion check")?;let prior=unlocked.accounting.clone();ensure!(unlocked.accounting.post_sales_command(SalesCommand::Order(duplicate)).is_err()&&unlocked.accounting==prior,"new source/reference cannot convert same approved quote again");
    let first_quote=unlocked.quotes[0].clone();unlocked.revise(&first_quote.id)?;unlocked.draft.notes="new legitimate quote revision".into();let revised_id=unlocked.approve()?;ensure!(revised_id!=first_quote.id&&unlocked.quotes[0].version==1&&unlocked.quotes[1].version==2&&serde_json::to_value(&unlocked.quotes[0])?==serde_json::to_value(&first_quote)?&&unlocked.accounting==prior,"new approved revision retains linked original quote/order exactly");
    unlocked.new_draft()?;unlocked.draft.customer="dual role A".into();unlocked.draft.phone="09123456789".into();unlocked.draft.lines=vec![OrderLine{query:"A".into(),quantity_milli:3000,chosen_code:Some("A".into())}];unlocked.draft.tax_basis_points=1000;unlocked.draft.discount_rial=2;let taxed_id=unlocked.approve()?;let taxed=unlocked.quotes.iter().find(|q|q.id==taxed_id).unwrap();ensure!(taxed.total_rial==54&&taxed.tax_rial==5,"synthetic user-configured quote tax input rounds49×0.1 to5, total54; no legal rate claim");let before=serde_json::to_value(&unlocked)?;ensure!(unlocked.sales_draft_from_quote(&taxed_id,&company).is_err()&&serde_json::to_value(&unlocked)?==before,"tax-bearing historical quote conversion blocked without stripping/changing tax");unlocked.validate()?;
    store.backup(&out.join("authentic-linked-backup.json"))?;let mut restored=Store::open(&out.join("fresh-restored"))?;restored.restore(Store::restore_preview(&out.join("authentic-linked-backup.json"))?)?;ensure!(serde_json::to_value(&restored.state)?==serde_json::to_value(&store.state)?,"authentic linked State/drafts/history fresh restore exact");
    observations.push(json!({"check":"raw invalid save/restart/failure + authentic49IRR conversion + postsubmit identical/alias retry after lock/restart + original version/metadata + preserved taxed54IRR quote","result":"passed","source_quote_total":49,"taxed_quote_total":54,"taxed_quote_tax":5}));
    fs::write(out.join("quote-draft-observations.json"),serde_json::to_vec_pretty(&observations)?)?;fs::write(out.join("authentic-state.json"),serde_json::to_vec_pretty(&store.state)?)?;fs::write(out.join("revised-taxed-source-state.json"),serde_json::to_vec_pretty(&unlocked)?)?;
    println!("PASS {} independent authentic full quote metadata/mapping/raw draft/retry/revision/tax-preservation observations; exact49IRR source and54IRR taxed historical quote.",observations.len());Ok(())
}
